import { Scene } from "retiam";
import { Physics2D } from "retiam/physics";

const scene = new Scene();

// Initialize 2D Physics with Rapier or Planck
const physics = new Physics2D(scene, {
    backend: "rapier",        // 'rapier' (WASM) or 'planck' (Box2D)
    gravity: [0, -9.8],       // [gx, gy] in m/s^2
    autoStep: true            // Automatically stepped in Scene render loop
});

physics.enableMouseDrag({
    frequencyHz: 6.0,   // Spring tightness for pulling bodies
    dampingRatio: 0.6,  // Damping to prevent uncontrolled oscillations
    maxForce: 1500      // Maximum pulling force multiplier
});

physics.on('collisionStart', (event: Collision2DEvent) => {
    console.log(`Collision between ${event.entityA.LABEL} and ${event.entityB.LABEL}`);
});

physics.on('collisionEnd', (event: Collision2DEvent) => {
    console.log('Bodies separated');
});

const bumper = new Circle(1.2);
const bodyComp = physics.add(bumper, 'static');

bodyComp.onCollisionStart((otherEntity, event) => {
    // Flash color or trigger particle effects on contact
    bumper.paint.fill = new Color(1.0, 0.9, 0.2, 1.0);
});

bodyComp.onCollisionEnd((otherEntity, event) => {
    bumper.paint.fill = new Color(0.3, 0.4, 0.5, 1.0);
});

const jelly = Poly.regular(8, 2.0);
jelly.transform.position = new Vec3(0, 10, 0);

physics.addSoftBody(jelly, {
    shape: 'radial',
    frequencyHz: 6.5,   // Elasticity / squishiness
    dampingRatio: 0.15,  // Jiggle damping
    friction: 0.4,
    restitution: 0.6
});

const curtain = new Poly([
    new Vec2(-3, 2.25),
    new Vec2(3, 2.25),
    new Vec2(3, -2.25),
    new Vec2(-3, -2.25)
], { isClosed: true });

physics.addSoftBody(curtain, {
    shape: 'grid',
    columns: 5,
    rows: 4,
    frequencyHz: 4.5,
    dampingRatio: 0.25,
    pinned: 'top-edge' // Top row is locked in place
});

const bobA = new Circle(0.6);
const bobB = new Circle(0.6);

// Creates physical spring AND procedural rendered spring coil
const { joint, visual } = physics.addSpring(bobA, bobB, {
    frequencyHz: 3.0,
    dampingRatio: 0.1,
    coils: 10,
    radius: 0.4,
    style: 'coil', // 'coil' | 'helix' | 'line'
    stroke: new Color(0.9, 0.6, 0.2, 1.0)
});
